-- Demo seed — Finance AR/AP: invoices + invoice_lines, payments + invoice_payments.
-- companyId anchors to core_companies row b3000000-0000-4000-8000-000000000001.
-- Idempotent: clears rows with INV-DEMO-/PAY-DEMO- number prefixes, then re-inserts.
-- NOTE: invoice_payments.invoiceId FK-references sales_invoices(id) (Prisma sales module),
-- so paid AR invoices are mirrored into sales_invoices to keep allocations valid; the
-- 3 pre-existing INV-PRJ-* rows in invoices are left untouched.
\set company '''b3000000-0000-4000-8000-000000000001'''

DELETE FROM invoice_payments WHERE "companyId" = :company AND "paymentNumber" LIKE 'PAY-DEMO-%';
DELETE FROM invoice_lines USING invoices i WHERE invoice_lines."invoiceId" = i.id AND i."invoiceNumber" LIKE 'INV-DEMO-%';
DELETE FROM payments WHERE "paymentNumber" LIKE 'PAY-DEMO-%';
DELETE FROM invoices WHERE "invoiceNumber" LIKE 'INV-DEMO-%';
DELETE FROM sales_invoices WHERE "companyId" = :company AND "invoiceNumber" LIKE 'INV-DEMO-%';

-- 40 invoices: 22 Paid, 6 Partially Paid, 7 Sent (current), 5 Overdue; 37 AR + 3 AP.
INSERT INTO invoices
  (id, "invoiceNumber", "invoiceType", "invoiceDate", "dueDate", "partyId", "partyName", "partyType",
   "companyId", subtotal, "taxAmount", "totalAmount", "paidAmount", "balanceAmount", "paymentTerms",
   "creditDays", currency, status, "isPosted", "taxBreakup", "createdBy", "createdAt", "updatedAt")
SELECT v.id::uuid, v.num, v.itype::invoices_invoicetype_enum, v.idate::date, v.ddate::date,
       COALESCE(c.id::text, 'demo-party-' || v.num), v.party, v.ptype, :company,
       v.sub, v.tax, v.total, v.paid, v.bal, v.terms, v.cdays, 'USD',
       v.status::invoices_status_enum, true,
       json_build_array(json_build_object('taxName','GST 18%','taxRate',18,'taxableAmount',v.sub,'taxAmount',v.tax)),
       'demo-seed', v.created::timestamp, v.updated::timestamp
